package env

import (
	"bytes"
	"encoding/base64"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"text/template"
)

// Files renders everything the install directory needs before the cluster
// exists: the compose file, the k3s config, the trust root for the chart
// repositories and the platform manifests. Keys are paths relative to the
// install directory. It is pure: nothing is read from the machine.
func Files(e Env) (map[string][]byte, error) {
	out := map[string][]byte{}
	for path, tmpl := range templates {
		data, err := render(tmpl, e)
		if err != nil {
			return nil, fmt.Errorf("%s: %w", path, err)
		}
		out[path] = data
	}
	for _, name := range []string{"certs/isrg-root-yr.pem", "certs/05e55783.0", "certs/558fe057.0"} {
		out[name] = []byte(isrgRootYR)
	}
	if !e.HasDatabase() {
		delete(out, PlatformDir+"/40-oracle.yaml")
	}
	return out, nil
}

// Write puts files into dir, creating directories as needed. Existing files
// are overwritten (install is idempotent); nothing else in dir is touched.
func Write(dir string, files map[string][]byte) error {
	paths := make([]string, 0, len(files))
	for p := range files {
		paths = append(paths, p)
	}
	sort.Strings(paths)
	for _, p := range paths {
		full := filepath.Join(dir, filepath.FromSlash(p))
		if err := os.MkdirAll(filepath.Dir(full), 0o755); err != nil {
			return err
		}
		mode := os.FileMode(0o644)
		if strings.HasSuffix(p, ".key") {
			mode = 0o600
		}
		if err := os.WriteFile(full, files[p], mode); err != nil {
			return err
		}
	}
	return nil
}

// TLSSecretManifest is the TLS secret of the API host, from the mkcert
// certificate. Written once the certificate exists.
func TLSSecretManifest(e Env, cert, key []byte) []byte {
	return []byte(fmt.Sprintf(`# The API host's certificate (issued by mkcert into certs/), terminated at NGINX like on the real clusters.
apiVersion: v1
kind: Secret
metadata:
  name: %s
  namespace: %s
type: kubernetes.io/tls
data:
  tls.crt: %s
  tls.key: %s
`, TLSSecret, e.Namespace, base64.StdEncoding.EncodeToString(cert), base64.StdEncoding.EncodeToString(key)))
}

// RancherUIManifest exposes the Rancher UI, which runs in the container
// next to k3s (not as a pod), through the same NGINX: a selector-less
// Service whose endpoint is the node's address, and an Ingress for the
// rancher host. The controller-wide prefix-strip snippet is overridden
// here, because Rancher serves the whole path space.
func RancherUIManifest(e Env, nodeIP string) ([]byte, error) {
	return render(rancherUITemplate, struct {
		Env
		NodeIP string
	}{e, nodeIP})
}

func render(tmpl *template.Template, data any) ([]byte, error) {
	var b bytes.Buffer
	if err := tmpl.Execute(&b, data); err != nil {
		return nil, err
	}
	return b.Bytes(), nil
}

func must(name, text string) *template.Template {
	return template.Must(template.New(name).Funcs(template.FuncMap{"indent": indent}).Parse(text))
}

func indent(n int, s string) string {
	pad := strings.Repeat(" ", n)
	lines := strings.Split(strings.TrimRight(s, "\n"), "\n")
	for i, l := range lines {
		if l != "" {
			lines[i] = pad + l
		}
	}
	return strings.Join(lines, "\n")
}

// NGINX variables ($request_uri, ...) are literal text to text/template;
// only {{ }} is special, so the snippets below render verbatim.
var templates = map[string]*template.Template{
	ComposeFile: must("compose", `# Generated by go-dark for team {{.Team}}: the local environment "{{.Name}}".
# Rancher with its embedded k3s cluster in one privileged container.
#   docker compose -f docker-compose.yaml up -d      start (first start pulls the image and creates the cluster)
#   docker compose -f docker-compose.yaml stop       stop, keeping the cluster
#   docker compose -f docker-compose.yaml down -v    remove everything, including the cluster and database
name: {{.Project}}

volumes:
  k3s: {}      # /var/lib/rancher: etcd, the cluster state, the Rancher admin user, the database files
  kubelet: {}
  cni: {}
  log: {}

services:
  rancher:
    image: {{.RancherImage}}
    container_name: {{.Container}}
    privileged: true
    restart: unless-stopped
    ports:
      # The host's 80/443 go straight to the NGINX ingress NodePorts: TLS
      # terminates at NGINX, like on the real clusters.
      - "80:{{.HTTPNodePort}}"
      - "443:{{.HTTPSNodePort}}"
      # The k3s API, on loopback only, for the kube context {{.Context}}.
      # go-dark refuses any context whose server isn't a loopback address.
      - "127.0.0.1:{{.APIPort}}:6443"
    volumes:
      - k3s:/var/lib/rancher
      - kubelet:/var/lib/kubelet
      - cni:/var/lib/cni
      - log:/var/log
      # etcd quota, compaction, event TTL and the node label; see the file.
      - ./k3s/config.yaml:/etc/rancher/k3s/config.yaml:ro
      # Let's Encrypt issues through the "YR" intermediates, whose root (ISRG
      # Root YR) the rancher image doesn't ship, so the helm-controller can't
      # fetch the ingress and reloader charts without it. The image looks CAs
      # up by hashed file name, hence the copies.
      - ./certs/isrg-root-yr.pem:/etc/rancher/ssl/isrg-root-yr.pem:ro
      - ./certs/05e55783.0:/etc/rancher/ssl/05e55783.0:ro
      - ./certs/558fe057.0:/etc/rancher/ssl/558fe057.0:ro
    environment:
      # Deterministic admin password for the Rancher UI (https://{{.RancherHost}}).
      - CATTLE_BOOTSTRAP_PASSWORD=developer
      # The image sets SSL_CERT_DIR to a directory that only exists once
      # something is mounted there; without the image's own trust store next
      # to it every outbound TLS call fails.
      - SSL_CERT_DIR=/etc/ssl/certs:/etc/rancher/ssl
      - SSL_CERT_FILE=/etc/ssl/ca-bundle.pem
`),

	K3sConfigFile: must("k3s", `# Read by the k3s server Rancher embeds (/etc/rancher/k3s/config.yaml).
#
# etcd protection: the default 2 GiB quota once filled up with Kubernetes
# events that never expired and the cluster refused to start. A larger quota
# buys headroom, periodic compaction drops old revisions and a short event
# TTL bounds the churn of crash-looping pods.
etcd-arg:
  - "quota-backend-bytes=8589934592"
  - "auto-compaction-mode=periodic"
  - "auto-compaction-retention=30m"
kube-apiserver-arg:
  - "event-ttl=30m"
# The charts' nodeSelector wants the environment's node label.
node-label:
  - "{{.NodeLabel}}"
`),

	PlatformDir + "/00-namespace.yaml": must("namespace", `# One namespace for the whole application, labelled with the environment.
apiVersion: v1
kind: Namespace
metadata:
  name: {{.Namespace}}
  labels:
    belgiantrain.be/environment: {{.Name}}
`),

	PlatformDir + "/10-nginx-ingress.yaml": must("nginx", `# NGINX Inc ingress controller (chart nginx-ingress {{.NginxChartVer}}), installed by
# k3s' helm-controller from this HelmChart, so it shows as an app in Rancher.
# Same controller family as the real clusters: the charts' nginx.org/*
# annotations and mergeable (master/minion) ingresses work unchanged.
# IngressClass {{.IngressClass}} is the default class, because the charts only
# map the real environments to a class and render an empty one for {{.Name}}.
apiVersion: helm.cattle.io/v1
kind: HelmChart
metadata:
  name: nginx-ingress
  namespace: kube-system
spec:
  chart: nginx-ingress
  repo: https://helm.nginx.com/stable
  version: {{.NginxChartVer}}
  targetNamespace: nginx-ingress
  createNamespace: true
  valuesContent: |-
    controller:
      ingressClass:
        name: {{.IngressClass}}
        create: true
        setAsDefaultIngress: true
      enableSnippets: true
      config:
        entries:
{{- if .Ingress.StripPrefix}}
          # The charts route /<service> with nginx.org/rewrites "rewrite=/",
          # which NGINX renders as proxy_pass http://upstream/ - so
          # /order/actuator/health reaches the service as //actuator/health.
          # This strips the first path segment in every location instead
          # ("rewrite ... break" makes NGINX pass the rewritten URI) and sends
          # it as X-Forwarded-Prefix, so Spring builds links under it. An
          # ingress's own nginx.org/location-snippets annotation overrides
          # this (the Rancher UI's does).
          http-snippets: |
            map $request_uri $gd_forwarded_prefix {
              ~^(?<gd_prefix>/[^/?]+) $gd_prefix;
              default "";
            }
          location-snippets: |
            rewrite ^/[^/]+(/.*)$ $1 break;
            proxy_set_header X-Forwarded-Prefix $gd_forwarded_prefix;
{{- end}}
          proxy-protocol: "False"
          real-ip-header: "X-Forwarded-For"
      service:
        # NodePort, not LoadBalancer: there is no cloud load balancer here.
        # The container publishes the host's 80/443 to these ports.
        type: NodePort
        httpPort:
          nodePort: {{.HTTPNodePort}}
        httpsPort:
          nodePort: {{.HTTPSNodePort}}
      resources:
        requests:
          cpu: 50m
          memory: 64Mi
`),

	PlatformDir + "/20-reloader.yaml": must("reloader", `# Stakater Reloader (chart {{.ReloaderVer}}): the charts' deployments carry
# reloader annotations, so config changes restart them like on the real clusters.
apiVersion: helm.cattle.io/v1
kind: HelmChart
metadata:
  name: reloader
  namespace: kube-system
spec:
  chart: reloader
  repo: https://stakater.github.io/stakater-charts
  version: {{.ReloaderVer}}
  targetNamespace: reloader
  createNamespace: true
  valuesContent: |-
    reloader:
      watchGlobally: true
`),

	PlatformDir + "/30-api-master.yaml": must("master", `# The mergeable master for the shared API host. Each service chart renders a
# minion (nginx.org/mergeable-ingress-type: minion) for its own path; without
# a master NGINX ignores the minions. TLS: platform/35-api-tls.yaml (mkcert).
apiVersion: networking.k8s.io/v1
kind: Ingress
metadata:
  name: {{.MasterIngress}}
  namespace: {{.Namespace}}
  annotations:
    nginx.org/mergeable-ingress-type: master
  labels:
    app.kubernetes.io/part-of: {{.Application}}
    belgiantrain.be/environment: {{.Name}}
spec:
  ingressClassName: {{.IngressClass}}
  tls:
    - hosts:
        - {{.APIHost}}
      secretName: {{.TLSSecret}}
  rules:
    - host: {{.APIHost}}
`),

	PlatformDir + "/40-oracle.yaml": must("oracle", `# Oracle Free ({{.OracleImage}}): the real environments share one Oracle with
# a schema per service; here one pod with the same users (created by go-dark
# from the services' config, see README.md).
apiVersion: v1
kind: Secret
metadata:
  name: oracle
  namespace: {{.Namespace}}
stringData:
  password: {{.DBPassword}}
---
apiVersion: v1
kind: Service
metadata:
  name: oracle
  namespace: {{.Namespace}}
spec:
  selector:
    app.kubernetes.io/name: oracle
  ports:
    - name: sqlnet
      port: 1521
---
apiVersion: apps/v1
kind: StatefulSet
metadata:
  name: oracle
  namespace: {{.Namespace}}
spec:
  serviceName: oracle
  replicas: 1
  selector:
    matchLabels:
      app.kubernetes.io/name: oracle
  template:
    metadata:
      labels:
        app.kubernetes.io/name: oracle
    spec:
      # hostPath ignores fsGroup: hand the directory to the image's oracle user.
      initContainers:
        - name: chown
          image: busybox:1.36
          command: ["sh", "-c", "chown -R 54321:54321 /opt/oracle/oradata"]
          volumeMounts:
            - name: data
              mountPath: /opt/oracle/oradata
      containers:
        - name: oracle
          image: {{.OracleImage}}
          env:
            - name: ORACLE_PASSWORD
              valueFrom:
                secretKeyRef:
                  name: oracle
                  key: password
          ports:
            - containerPort: 1521
          readinessProbe:
            exec:
              command: ["healthcheck.sh"]
            periodSeconds: 10
            failureThreshold: 60
          resources:
            requests:
              cpu: 250m
              memory: 1Gi
            limits:
              memory: 3Gi
          volumeMounts:
            - name: data
              mountPath: /opt/oracle/oradata
      # No storage class in this cluster; /var/lib/rancher is the k3s volume,
      # so the data survives recreating the container.
      volumes:
        - name: data
          hostPath:
            path: /var/lib/rancher/go-dark/oracle
            type: DirectoryOrCreate
`),

	ReadmeFile: must("readme", `# go-dark environment "{{.Name}}" of team {{.Team}}

Generated by go-dark; "install / repair" rewrites these files. Everything here
runs without go-dark too:

    docker compose -f docker-compose.yaml up -d
    # wait for k3s (a minute), then the platform:
    docker exec {{.Container}} cat /etc/rancher/k3s/k3s.yaml   # the cluster's kubeconfig
    kubectl --context {{.Context}} apply -f platform/

| | |
|---|---|
| Container / compose project | {{.Container}} / {{.Project}} |
| Kube context | {{.Context}} (https://127.0.0.1:{{.APIPort}}, loopback only) |
| Namespace | {{.Namespace}} |
| Services | {{.APIURL}}/<service path> |
| Rancher UI | https://{{.RancherHost}} (admin / developer) |
| IngressClass | {{.IngressClass}} (default), NodePorts {{.HTTPNodePort}}/{{.HTTPSNodePort}} published as 80/443 |
| Node label | {{.NodeLabel}} |
{{- if .HasDatabase}}
| Database | {{.DBURL}} (users: see go-dark's install log; password in platform/40-oracle.yaml) |
{{- end}}

Hosts file: {{.HostsLine}}
Certificates: certs/tls.crt and certs/tls.key, issued by mkcert for those hosts.
`),
}

var rancherUITemplate = must("rancher-ui", `# The Rancher UI runs in the container next to k3s, not as a pod: a Service
# without selector whose endpoint is the node, reached through the same NGINX
# as the services. Rancher serves the whole path space, so the controller-wide
# prefix strip is overridden with a no-op snippet.
apiVersion: v1
kind: Service
metadata:
  name: rancher
  namespace: {{.Namespace}}
spec:
  ports:
    - name: https
      port: 443
---
apiVersion: v1
kind: Endpoints
metadata:
  name: rancher
  namespace: {{.Namespace}}
subsets:
  - addresses:
      - ip: {{.NodeIP}}
    ports:
      - name: https
        port: 443
---
apiVersion: networking.k8s.io/v1
kind: Ingress
metadata:
  name: rancher
  namespace: {{.Namespace}}
  annotations:
    nginx.org/ssl-services: "rancher"
    nginx.org/websocket-services: "rancher"
    nginx.org/location-snippets: |
      proxy_set_header X-Forwarded-Prefix "";
spec:
  ingressClassName: {{.IngressClass}}
  tls:
    - hosts:
        - {{.RancherHost}}
      secretName: {{.TLSSecret}}
  rules:
    - host: {{.RancherHost}}
      http:
        paths:
          - pathType: Prefix
            path: /
            backend:
              service:
                name: rancher
                port:
                  number: 443
`)

// Template accessors for the constants.
func (Env) RancherImage() string  { return RancherImage }
func (Env) OracleImage() string   { return OracleImage }
func (Env) NginxChartVer() string { return NginxChartVer }
func (Env) ReloaderVer() string   { return ReloaderVer }
func (Env) TLSSecret() string     { return TLSSecret }
func (Env) MasterIngress() string { return MasterIngress }
func (Env) APIPort() int          { return APIPort }
func (Env) HTTPNodePort() int     { return HTTPNodePort }
func (Env) HTTPSNodePort() int    { return HTTPSNodePort }

